// Des: One-URL pipeline: fetch, convert, validate, store once, index
// Flo: canonical URL > cached etag > own GET with deadline > pageSave: 304 touch or 2xx convert to UTF-8, validate, save by hash, upsert index + record + log in one transaction
// I/O: URL + Conf + open Db + data dir (caller) > Outc (status word, code, hash); pageSave also takes vendor results (Got)
// ===================================================================
const std = @import("std"); const revi = @import("ru-revi-sche.zig"); const outb = @import("sy-clou-outb.zig"); const vali = @import("sc-reco-vali.zig"); const stru = @import("pa-stru-data.zig"); const html = @import("pa-html-text.zig"); const urln = @import("ut-urlz-norm.zig"); const fetc = @import("nt-fetc-owns.zig"); const tmfx = @import("nt-fetc-time.zig"); const chrs = @import("pa-char-dete.zig"); const file = @import("st-stor-file.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .vers = "scra/0.1.0", .nxtm = 86400000, .rawd = "raw" };
pub const Outc = struct { urlz: []const u8, code: u16, stat: []const u8, hexz: []const u8, size: usize, kind: []const u8 = "", retr: u32 = 0, tier: i64 = 1, vend: []const u8 = "", cred: u32 = 0, micr: u64 = 0 };
pub const Got = struct { code: u16, ctyp: []const u8, body: []const u8, etag: []const u8 = "", lmod: []const u8 = "", retr: u32 = 0, tier: i64 = 1, vend: []const u8 = "", cred: i64 = 0, micr: i64 = 0 };
fn recoMake(aren: std.mem.Allocator, utf8: []const u8) !inde.Reco { const blks = try stru.blokFind(aren, utf8); for (blks) |blk| if (blk.kind == .ldjs and std.json.validate(aren, blk.json) catch false) return .{ .hexz = "", .kind = "ldjs", .body = blk.json }; for (blks) |blk| if (blk.kind == .next and std.json.validate(aren, blk.json) catch false) return .{ .hexz = "", .kind = "next", .body = blk.json }; const titl = (try html.htmlTitl(aren, utf8)) orelse ""; const text = try html.htmlText(aren, utf8); return .{ .hexz = "", .kind = "text", .body = try std.fmt.allocPrint(aren, "{s}\n{s}", .{ titl, text }) }; }
pub fn optsMake(aren: std.mem.Allocator, conf: cfgz.Conf, priv: bool) !fetc.Opts { const uagt = if (conf.uagt_cont_mail.len > 0) try std.fmt.allocPrint(aren, "{s} (+{s})", .{ CF.vers, conf.uagt_cont_mail }) else CF.vers; return .{ .time_mill = conf.fetc_time_seco * 1000, .body_maxz = conf.fetc_body_maxz, .redi_maxz = conf.fetc_redi_maxz, .uagt = uagt, .priv_allo = priv }; }
pub fn nowMs(iozz: std.Io) i64 { return @intCast(std.Io.Clock.real.now(iozz).toMilliseconds()); }
fn logzOne(dbzz: *sqli.Db, urlz: []const u8, got: Got, note: []const u8, timz: i64) !void { try inde.logzAdd(dbzz, .{ .urlz = urlz, .code = got.code, .tier = got.tier, .vend = got.vend, .cred = got.cred, .micr = got.micr, .robo = "none", .timz = timz, .note = note }); }
pub fn pageFetc(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Db, dirz: []const u8, urlz: []const u8, priv: bool) !Outc { const norm = try urln.urlNorm(aren, urlz); const prev = try inde.pageGet(dbzz, aren, norm); const cond: fetc.Cond = if (prev) |row| .{ .etag = row.etag, .lmod = row.lmod } else .{}; const timz = nowMs(iozz); var resp = tmfx.fetcTime(gpaz, iozz, urlz, try optsMake(aren, conf, priv), cond) catch |err| { try logzOne(dbzz, norm, .{ .code = 0, .ctyp = "", .body = "" }, @errorName(err), timz); return err; }; defer resp.free(gpaz); return pageSave(aren, iozz, conf, dbzz, dirz, norm, prev, .{ .code = resp.code, .ctyp = resp.ctyp, .body = resp.body, .etag = resp.etag, .lmod = resp.lmod, .retr = resp.retr }); }
pub fn pageSave(aren: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Db, dirz: []const u8, norm: []const u8, prev: ?inde.Row, got: Got) !Outc { const timz = nowMs(iozz);
if (got.code == 304 and prev != null) { const row = prev.?; var upd = row; upd.fetc = timz; upd.intv = revi.reviNext(row, false, conf); upd.next = timz + upd.intv; try dbzz.exec("BEGIN IMMEDIATE;"); errdefer dbzz.exec("ROLLBACK;") catch {}; try inde.pageSet(dbzz, norm, upd); try logzOne(dbzz, norm, got, "not modified", timz); try dbzz.exec("COMMIT;"); return .{ .urlz = norm, .code = 304, .stat = "notm", .hexz = row.hexz, .size = 0 }; }
if (got.code < 200 or got.code >= 300) { try logzOne(dbzz, norm, got, "http status, not stored", timz); return .{ .urlz = norm, .code = got.code, .stat = "http", .hexz = "", .size = 0, .retr = got.retr }; }
const utf8 = try chrs.utf8Conv(aren, chrs.charFind(got.ctyp, got.body), got.body); const verd = try vali.pageVali(aren, got.ctyp, utf8); if (verd != .okay) { try logzOne(dbzz, norm, got, try std.fmt.allocPrint(aren, "rejected: {s}", .{@tagName(verd)}), timz); return .{ .urlz = norm, .code = got.code, .stat = @tagName(verd), .hexz = "", .size = 0 }; } const rawd = try std.fs.path.join(aren, &.{ dirz, CF.rawd }); const saved = try file.fileSave(aren, iozz, rawd, utf8); const same = prev != null and std.mem.eql(u8, prev.?.hexz, &saved.hexz); const hexz = try aren.dupe(u8, &saved.hexz); const intv = revi.reviNext(prev, prev != null and !same, conf);
try dbzz.exec("BEGIN IMMEDIATE;"); errdefer dbzz.exec("ROLLBACK;") catch {}; try inde.pageSet(dbzz, norm, .{ .hexz = hexz, .etag = got.etag, .lmod = got.lmod, .code = got.code, .tier = got.tier, .vend = got.vend, .fetc = timz, .next = timz + intv, .intv = intv }); try logzOne(dbzz, norm, got, if (same) "same content" else "stored", timz); var reco = try recoMake(aren, utf8); reco.hexz = hexz; try inde.recoSet(dbzz, norm, reco, timz); if (!same) { try outb.outbAdd(dbzz, "file", hexz, timz, false); try outb.outbAdd(dbzz, "rec", norm, timz, true); } try dbzz.exec("COMMIT;");
return .{ .urlz = norm, .code = got.code, .stat = if (same) "same" else "new", .hexz = hexz, .size = utf8.len, .kind = reco.kind }; }
